"""Score the index warm-up runs: medians [range] per arm of rpc_s, end_s, cpu_s and read_MB from results.csv,
and each column's ratio of medians against the base arm, with an overlap check (disjoint ranges = "no overlap").
usage: python3 warmup_score.py <dir with results.csv> [--base A] [--arm W]"""
import csv, os, statistics, sys

args = sys.argv[1:]
if not args:
    sys.exit(__doc__)
d = args[0]
base = args[args.index("--base") + 1] if "--base" in args else "A"
arm = args[args.index("--arm") + 1] if "--arm" in args else "W"
rows = list(csv.DictReader(open(os.path.join(d, "results.csv"))))
cols = ["rpc_s", "end_s", "cpu_s", "read_MB"]
bad = [r["run"] for r in rows if r["hash_match"] != "yes"]
print(f"runs {len(rows)}; hash mismatches: {bad if bad else 'none'}")
val = {a: {c: [float(r[c]) for r in rows if r["arm"] == a] for c in cols} for a in (base, arm)}
print(f"{'arm':4} {'n':>2}  " + "  ".join(f"{c:24}" for c in cols))
for a in (base, arm):
    print(f"{a:4} {len(val[a]['rpc_s']):>2}  " + "  ".join(
        f"{statistics.median(val[a][c]):g} [{min(val[a][c]):g}-{max(val[a][c]):g}]".ljust(24) for c in cols))
for c in cols:
    m0, m1 = statistics.median(val[base][c]), statistics.median(val[arm][c])
    disjoint = max(val[arm][c]) < min(val[base][c]) or min(val[arm][c]) > max(val[base][c])
    print(f"{arm}/{base} {c}: {m1 / m0:.3f} ({(m1 / m0 - 1) * 100:+.1f}%, {'no overlap' if disjoint else 'overlap'})")
